generated_path('data/proofs/generated').
repos_path('data/proofs/repos').

% ═══════════════════════════════════════════════════════════
% GÖDEL ENCODING (Type → Prime)
% ═══════════════════════════════════════════════════════════

type_prime(file, 2).
type_prime(function, 3).
type_prime(fact, 5).
type_prime(proof, 7).
type_prime(parquet, 11).
type_prime(repo, 13).
type_prime(module, 17).
type_prime(struct, 19).
type_prime(enum, 23).
type_prime(trait, 29).
type_prime(impl, 31).
type_prime(const, 37).
type_prime(static, 41).
type_prime(fn, 43).
type_prime(macro, 47).
type_prime(type, 53).
type_prime(use, 59).
type_prime(mod, 61).
type_prime(pub, 67).
type_prime(crate, 71).

% ═══════════════════════════════════════════════════════════
