% ═══════════════════════════════════════════════════════════

universe_level(0, table).      % Base tables
universe_level(1, meta).       % Meta-tables
universe_level(2, meta_meta).  % Meta-meta
universe_level(71, universe).  % Top level

% ═══════════════════════════════════════════════════════════
