% ═══════════════════════════════════════════════════════════

complexity_source(oeis, 'https://oeis.org').
complexity_source(monster, 'Monster group').
complexity_source(hecke, 'Hecke operators').
complexity_source(galois, 'Galois theory').

% ═══════════════════════════════════════════════════════════
% HELPER PREDICATES
% ═══════════════════════════════════════════════════════════

% Check if prime is Monster prime
is_monster_prime(P) :- monster_prime(P).

% Get emoji for prime
prime_emoji(P, E) :- emoji_prime(P, E).

% Get prime for type
type_to_prime(T, P) :- type_prime(T, P).

% Gödel encode: multiply primes
godel_encode([], 1).
godel_encode([P|Ps], G) :-
    godel_encode(Ps, G0),
    G is P * G0.

